<?php
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/helpers.php';requerirRol(['departamento']);
requerirCorreoConfirmado($pdo);$u=usuarioActual();$q=$pdo->prepare("SELECT t.*,TRIM(CONCAT(COALESCE(p.nombre,''),' ',COALESCE(p.apellido,''))) AS analista FROM tickets t LEFT JOIN usuarios a ON a.id_usuarios=t.analista_id LEFT JOIN perfiles_usuarios p ON p.usuario_id=a.id_usuarios WHERE t.departamento_id=? ORDER BY t.fecha_creacion DESC");$q->execute([$u['departamento_id']]);$tickets=$q->fetchAll();$pg=paginar($tickets);$tickets=$pg['items'];?><!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mis tickets</title><link rel="icon" href="../assets/img/logo.png"><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet" integrity="sha384-QWTKZyjpPEjISv5WaRU9OFeRpok6YctnYmDr5pNlyT2bRjXh0JMhjY6hW+ALEwIH" crossorigin="anonymous"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.css" rel="stylesheet" integrity="sha384-tViUnnbYAV00FLIhhi3v/dWt3Jxw4gZQcNoSCxCIFNJVCx7/D55/wXsrNIRANwdD" crossorigin="anonymous"><link href="../assets/css/style.css" rel="stylesheet"></head><body><div class="app-shell"><?php include __DIR__ . '/../includes/sidebar.php'; ?><div class="main"><?php include __DIR__.'/../includes/topbar.php'; ?><div class="content"><div class="card-panel"><div class="panel-head"><h2>Tickets de <?=h($u['departamento_nombre'])?></h2><a class="btn btn-brand btn-sm" href="crear_ticket.php">Nuevo ticket</a></div><div class="table-responsive"><table class="table align-middle mb-0 mobile-stack-table"><thead><tr><th>Ticket</th><th>Problema</th><th>Fecha</th><th>Estado</th><th>Analista</th></tr></thead><tbody><?php foreach($tickets as $t): ?><tr><td data-label="Ticket"><a href="ver_ticket.php?id=<?=(int)$t['id_tickets']?>">#<?=str_pad((string)$t['id_tickets'],6,'0',STR_PAD_LEFT)?></a></td><td data-label="Problema"><?=h($t['titulo'])?></td><td data-label="Fecha"><?=date('d/m/Y H:i',strtotime($t['fecha_creacion']))?></td><td data-label="Estado"><?=h(ucfirst(str_replace('_',' ',$t['estado'])))?></td><td data-label="Analista"><?=h($t['analista']?:'Sin asignar')?></td></tr><?php endforeach;if(!$tickets): ?><tr><td colspan="5" class="text-center text-muted py-4">No hay tickets registrados.</td></tr><?php endif;?></tbody></table></div><div class="panel-body"><?=renderPaginacion($pg)?></div></div></div></div></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js" integrity="sha384-YvpcrYf0tY3lHB60NNkmXc5s9fDVZLESaAA55NDzOxhy9GkcIdslK1eN7N6jIeHz" crossorigin="anonymous"></script></body></html>